    CONSTRAINT replenishment_requests_concurrency_version_check CHECK ((concurrency_version > 0)),
    CONSTRAINT replenishment_requests_fulfilled_quantity_check CHECK ((fulfilled_quantity >= (0)::numeric)),
    CONSTRAINT replenishment_requests_requested_quantity_check CHECK ((requested_quantity > (0)::numeric)),
    CONSTRAINT replenishment_requests_status_check CHECK ((status = ANY (ARRAY['requested'::text, 'approved'::text, 'in_progress'::text, 'fulfilled'::text, 'cancelled'::text])))
);


