SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: kitchen_adjustments; Type: TABLE; Schema: public; Owner: nexaconnect_migration
--

CREATE TABLE public.kitchen_adjustments (
    id uuid NOT NULL,
    source_message_id uuid NOT NULL,
    order_id uuid NOT NULL,
    order_line_id uuid,
    adjustment_type text NOT NULL,
    quantity_delta numeric(12,3),
    instructions jsonb DEFAULT '{}'::jsonb NOT NULL,
    received_at_utc timestamp with time zone NOT NULL,
    applied_at_utc timestamp with time zone,
    status text NOT NULL,
    CONSTRAINT ck_kitchen_adjustments_instructions CHECK ((jsonb_typeof(instructions) = 'object'::text)),
    CONSTRAINT ck_kitchen_adjustments_status CHECK ((status = ANY (ARRAY['received'::text, 'applied'::text, 'rejected'::text]))),
    CONSTRAINT ck_kitchen_adjustments_type CHECK ((adjustment_type = ANY (ARRAY['add'::text, 'quantity_change'::text, 'cancel'::text, 'void'::text])))
);


ALTER TABLE public.kitchen_adjustments OWNER TO nexaconnect_migration;

--
-- Name: kitchen_status_history; Type: TABLE; Schema: public; Owner: nexaconnect_migration
--

CREATE TABLE public.kitchen_status_history (
    id uuid NOT NULL,
    kitchen_ticket_id uuid NOT NULL,
    kitchen_ticket_item_id uuid,
    entity_type text NOT NULL,
    from_status text,
    to_status text NOT NULL,
    reason_code text,
    changed_at_utc timestamp with time zone NOT NULL,
    changed_by text NOT NULL,
    CONSTRAINT ck_kitchen_status_history_entity CHECK ((((entity_type = 'ticket'::text) AND (kitchen_ticket_item_id IS NULL)) OR ((entity_type = 'item'::text) AND (kitchen_ticket_item_id IS NOT NULL)))),
    CONSTRAINT ck_kitchen_status_history_to_status CHECK ((to_status = ANY (ARRAY['queued'::text, 'in_progress'::text, 'ready'::text, 'completed'::text, 'cancelled'::text])))
);


ALTER TABLE public.kitchen_status_history OWNER TO nexaconnect_migration;

--
-- Name: kitchen_ticket_items; Type: TABLE; Schema: public; Owner: nexaconnect_migration
--

CREATE TABLE public.kitchen_ticket_items (
    id uuid NOT NULL,
    kitchen_ticket_id uuid NOT NULL,
    order_line_id uuid NOT NULL,
    product_id uuid NOT NULL,
    product_variant_id uuid,
    item_name_snapshot text NOT NULL,
    variant_name_snapshot text,
    modifiers_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    quantity numeric(12,3) NOT NULL,
    notes text,
    status text NOT NULL,
    queued_at_utc timestamp with time zone NOT NULL,
    started_at_utc timestamp with time zone,
    ready_at_utc timestamp with time zone,
    completed_at_utc timestamp with time zone,
    cancelled_at_utc timestamp with time zone,
    updated_at_utc timestamp with time zone NOT NULL,
    concurrency_version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT ck_kitchen_ticket_items_concurrency_version CHECK ((concurrency_version > 0)),
    CONSTRAINT ck_kitchen_ticket_items_modifiers CHECK ((jsonb_typeof(modifiers_snapshot) = 'array'::text)),
    CONSTRAINT ck_kitchen_ticket_items_name CHECK ((char_length(btrim(item_name_snapshot)) > 0)),
    CONSTRAINT ck_kitchen_ticket_items_quantity CHECK ((quantity > (0)::numeric)),
    CONSTRAINT ck_kitchen_ticket_items_status CHECK ((status = ANY (ARRAY['queued'::text, 'in_progress'::text, 'ready'::text, 'completed'::text, 'cancelled'::text])))
);


ALTER TABLE public.kitchen_ticket_items OWNER TO nexaconnect_migration;

--
-- Name: TABLE kitchen_ticket_items; Type: COMMENT; Schema: public; Owner: nexaconnect_migration
--

COMMENT ON TABLE public.kitchen_ticket_items IS 'Preparation snapshots only; Kitchen never recalculates commercial totals.';


--
-- Name: kitchen_tickets; Type: TABLE; Schema: public; Owner: nexaconnect_migration
--

CREATE TABLE public.kitchen_tickets (
    id uuid NOT NULL,
    restaurant_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    order_id uuid NOT NULL,
    preparation_station_id uuid NOT NULL,
    ticket_number text NOT NULL,
    service_sequence integer DEFAULT 1 NOT NULL,
    priority integer DEFAULT 0 NOT NULL,
    status text NOT NULL,
    queued_at_utc timestamp with time zone NOT NULL,
    started_at_utc timestamp with time zone,
    ready_at_utc timestamp with time zone,
    completed_at_utc timestamp with time zone,
    cancelled_at_utc timestamp with time zone,
    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    concurrency_version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT ck_kitchen_tickets_audit_timestamps CHECK ((updated_at_utc >= created_at_utc)),
    CONSTRAINT ck_kitchen_tickets_concurrency_version CHECK ((concurrency_version > 0)),
    CONSTRAINT ck_kitchen_tickets_priority CHECK ((priority >= 0)),
    CONSTRAINT ck_kitchen_tickets_sequence CHECK ((service_sequence > 0)),
    CONSTRAINT ck_kitchen_tickets_status CHECK ((status = ANY (ARRAY['queued'::text, 'in_progress'::text, 'ready'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT ck_kitchen_tickets_ticket_number CHECK ((char_length(btrim(ticket_number)) > 0))
);


ALTER TABLE public.kitchen_tickets OWNER TO nexaconnect_migration;

--
-- Name: COLUMN kitchen_tickets.order_id; Type: COMMENT; Schema: public; Owner: nexaconnect_migration
--

COMMENT ON COLUMN public.kitchen_tickets.order_id IS 'External Order service identifier; no cross-database foreign key.';


--
-- Name: COLUMN kitchen_tickets.preparation_station_id; Type: COMMENT; Schema: public; Owner: nexaconnect_migration
--

COMMENT ON COLUMN public.kitchen_tickets.preparation_station_id IS 'External Restaurant Management station identifier.';


--
-- Name: nexaconnect_schema_migrations; Type: TABLE; Schema: public; Owner: nexaconnect_migration
--

CREATE TABLE public.nexaconnect_schema_migrations (
    version integer NOT NULL,
    name text NOT NULL,
    metadata_checksum_sha256 text NOT NULL,
    up_checksum_sha256 text NOT NULL,
    down_checksum_sha256 text NOT NULL,
    downgrade_safety text NOT NULL,
    applied_at_utc timestamp with time zone DEFAULT now() NOT NULL,
    application_version text NOT NULL,
    execution_id uuid NOT NULL,
    CONSTRAINT nexaconnect_schema_migrations_application_version_check CHECK ((char_length(btrim(application_version)) > 0)),
    CONSTRAINT nexaconnect_schema_migrations_down_checksum_sha256_check CHECK ((down_checksum_sha256 ~ '^[0-9A-F]{64}$'::text)),
    CONSTRAINT nexaconnect_schema_migrations_downgrade_safety_check CHECK ((downgrade_safety = ANY (ARRAY['safe'::text, 'transformative'::text, 'destructive'::text, 'unsupported'::text]))),
    CONSTRAINT nexaconnect_schema_migrations_metadata_checksum_sha256_check CHECK ((metadata_checksum_sha256 ~ '^[0-9A-F]{64}$'::text)),
    CONSTRAINT nexaconnect_schema_migrations_name_check CHECK ((char_length(btrim(name)) > 0)),
    CONSTRAINT nexaconnect_schema_migrations_up_checksum_sha256_check CHECK ((up_checksum_sha256 ~ '^[0-9A-F]{64}$'::text)),
    CONSTRAINT nexaconnect_schema_migrations_version_check CHECK ((version > 0))
);


ALTER TABLE public.nexaconnect_schema_migrations OWNER TO nexaconnect_migration;

--
-- Name: outbox_messages; Type: TABLE; Schema: public; Owner: nexaconnect_migration
--

CREATE TABLE public.outbox_messages (
    id uuid NOT NULL,
    event_type text NOT NULL,
    contract_version integer NOT NULL,
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    payload jsonb NOT NULL,
    correlation_id text,
    causation_id text,
    occurred_at_utc timestamp with time zone NOT NULL,
    published_at_utc timestamp with time zone,
    retry_count integer DEFAULT 0 NOT NULL,
    next_attempt_at_utc timestamp with time zone,
    last_error_category text,
    CONSTRAINT ck_outbox_messages_published CHECK (((published_at_utc IS NULL) OR (published_at_utc >= occurred_at_utc))),
    CONSTRAINT outbox_messages_contract_version_check CHECK ((contract_version > 0)),
    CONSTRAINT outbox_messages_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT outbox_messages_retry_count_check CHECK ((retry_count >= 0))
);


ALTER TABLE public.outbox_messages OWNER TO nexaconnect_migration;

--
-- Name: processed_messages; Type: TABLE; Schema: public; Owner: nexaconnect_migration
--

CREATE TABLE public.processed_messages (
    message_id uuid NOT NULL,
    consumer_name text NOT NULL,
    processed_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT ck_processed_messages_consumer_name CHECK ((char_length(btrim(consumer_name)) > 0))
);


ALTER TABLE public.processed_messages OWNER TO nexaconnect_migration;

