--
-- Name: cash_movements; Type: TABLE; Schema: public; Owner: nexaconnect_migration
--

CREATE TABLE public.cash_movements (
    id uuid NOT NULL,
    cash_session_id uuid NOT NULL,
    movement_type text NOT NULL,
    amount numeric(19,4) NOT NULL,
    order_id uuid,
    payment_id uuid,
    reason_code text,
    occurred_at_utc timestamp with time zone NOT NULL,
    recorded_by text NOT NULL,
    CONSTRAINT cash_movements_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT cash_movements_movement_type_check CHECK ((movement_type = ANY (ARRAY['sale'::text, 'refund'::text, 'pay_in'::text, 'pay_out'::text, 'float_adjustment'::text])))
);


