--
-- Name: cash_sessions; Type: TABLE; Schema: public; Owner: nexaconnect_migration
--

CREATE TABLE public.cash_sessions (
    id uuid NOT NULL,
    store_id uuid NOT NULL,
    shift_id uuid NOT NULL,
    currency character(3) NOT NULL,
    opening_amount numeric(19,4) NOT NULL,
    expected_closing_amount numeric(19,4),
    actual_closing_amount numeric(19,4),
    variance_amount numeric(19,4),
    status text NOT NULL,
    opened_at_utc timestamp with time zone NOT NULL,
    closed_at_utc timestamp with time zone,
    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    concurrency_version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT cash_sessions_concurrency_version_check CHECK ((concurrency_version > 0)),
    CONSTRAINT cash_sessions_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT cash_sessions_opening_amount_check CHECK ((opening_amount >= (0)::numeric)),
    CONSTRAINT cash_sessions_status_check CHECK ((status = ANY (ARRAY['open'::text, 'counting'::text, 'closed'::text]))),
    CONSTRAINT ck_cash_sessions_audit CHECK ((updated_at_utc >= created_at_utc)),
    CONSTRAINT ck_cash_sessions_closed CHECK (((closed_at_utc IS NULL) OR (closed_at_utc >= opened_at_utc)))
);


ALTER TABLE public.cash_sessions OWNER TO nexaconnect_migration;

