    CONSTRAINT nexaconnect_schema_migrations_downgrade_safety_check CHECK ((downgrade_safety = ANY (ARRAY['safe'::text, 'transformative'::text, 'destructive'::text, 'unsupported'::text]))),
    CONSTRAINT nexaconnect_schema_migrations_metadata_checksum_sha256_check CHECK ((metadata_checksum_sha256 ~ '^[0-9A-F]{64}$'::text)),
    CONSTRAINT nexaconnect_schema_migrations_name_check CHECK ((char_length(btrim(name)) > 0)),
