    CONSTRAINT ck_support_elevations_approval CHECK ((((status = 'pending'::text) AND (approved_at_utc IS NULL) AND (expires_at_utc IS NULL) AND (approved_by_subject_id IS NULL)) OR ((status = ANY (ARRAY['active'::text, 'revoked'::text])) AND (approved_at_utc IS NOT NULL) AND (expires_at_utc > approved_at_utc) AND (approved_by_subject_id IS NOT NULL)) OR ((status = 'revoked'::text) AND (approved_at_utc IS NULL) AND (expires_at_utc IS NULL) AND (approved_by_subject_id IS NULL)))),
    CONSTRAINT ck_support_elevations_audit_timestamps CHECK ((updated_at_utc >= created_at_utc)),
    CONSTRAINT ck_support_elevations_duration CHECK (((duration_minutes >= 5) AND (duration_minutes <= 240))),
    CONSTRAINT ck_support_elevations_reason CHECK ((char_length(btrim(reason)) >= 10)),
    CONSTRAINT ck_support_elevations_revocation CHECK ((((status <> 'revoked'::text) AND (revoked_at_utc IS NULL) AND (revoked_by_subject_id IS NULL)) OR ((status = 'revoked'::text) AND (revoked_at_utc IS NOT NULL) AND (revoked_by_subject_id IS NOT NULL)))),
    CONSTRAINT ck_support_elevations_separation_of_duties CHECK (((approved_by_subject_id IS NULL) OR (approved_by_subject_id <> support_subject_id))),
    CONSTRAINT ck_support_elevations_status CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'revoked'::text]))),
    CONSTRAINT ck_support_elevations_support_subject CHECK ((char_length(btrim(support_subject_id)) > 0))
);


ALTER TABLE public.support_elevations OWNER TO nexaconnect_migration;

